schema_ddl:
CREATE TABLE SALESPERSON (
    SALES_ID INT,
    NAME VARCHAR(255),
    SALARY INT,
    COMMISSION_RATE INT,
    HIRE_DATE VARCHAR(255)
);

CREATE TABLE COMPANY (
    COM_ID INT,
    NAME VARCHAR(255),
    CITY VARCHAR(255)
);

CREATE TABLE ORDERS (
    ORDER_ID INT,
    COM_ID INT,
    SALES_ID INT,
    ORDER_DATE VARCHAR(255),
    AMOUNT INT
);

counterexample:
INSERT INTO SALESPERSON (SALES_ID, NAME) VALUES (1, 'Alice'), (2, 'Bob');
INSERT INTO COMPANY (COM_ID, NAME) VALUES (1, 'RED'), (2, 'BLUE');
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID) VALUES (1, 1, 1), (2, 2, 1);

